uv run python -c "
import types
from tinygrad.schedule.rangeify import remove_bufferize

def walk(code, depth=0, path='root'):
    probe = [n for n in code.co_names if n in ('AxisType','REDUCE','arg','ranges','any','partition')]
    print(f'depth {depth}: {code.co_name!r:20} freevars={code.co_freevars} probe_names={probe}')
    for c in code.co_consts:
        if isinstance(c, types.CodeType): walk(c, depth+1, path)
walk(remove_bufferize.__code__)
"
